package main

// entry is a node in the cache's intrusive doubly linked recency list.
type entry struct {
	key, value string
	prev, next *entry
}

// Cache is a fixed-capacity least-recently-used cache. All operations run in
// O(1) expected time.
type Cache struct {
	capacity int
	index    map[string]*entry
	// root is a sentinel: root.next is the most recently used entry and
	// root.prev the least recently used one.
	root entry
}

// NewCache returns an empty cache holding at most capacity keys.
func NewCache(capacity int) *Cache {
	c := &Cache{
		capacity: capacity,
		index:    make(map[string]*entry, min(capacity+1, 1<<20)),
	}
	c.root.next = &c.root
	c.root.prev = &c.root
	return c
}

// Set inserts or overwrites key, marking it most recently used, and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value []byte) {
	if e, ok := c.index[string(key)]; ok {
		e.value = string(value)
		c.moveToFront(e)
		return
	}
	e := &entry{key: string(key), value: string(value)}
	c.index[e.key] = e
	c.pushFront(e)
	if len(c.index) > c.capacity {
		lru := c.root.prev
		c.unlink(lru)
		delete(c.index, lru.key)
	}
}

// Get returns the value for key and marks it most recently used.
func (c *Cache) Get(key []byte) (string, bool) {
	e, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(e)
	return e.value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key []byte) bool {
	e, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.unlink(e)
	delete(c.index, e.key)
	return true
}

// Len returns the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

func (c *Cache) pushFront(e *entry) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache) unlink(e *entry) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev, e.next = nil, nil
}

func (c *Cache) moveToFront(e *entry) {
	if c.root.next == e {
		return
	}
	c.unlink(e)
	c.pushFront(e)
}

// Command app simulates an LRU cache driven by commands read from stdin.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	out := bufio.NewWriterSize(w, 1<<16)

	line, rest, _ := bytes.Cut(input, []byte{'\n'})
	cache := NewCache(parseCapacity(trim(line)))

	var num []byte
	for len(rest) > 0 {
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		cmd, args := nextToken(trim(line))
		switch string(cmd) {
		case "SET":
			key, args := nextToken(args)
			value, _ := nextToken(args)
			cache.Set(key, value)
		case "GET":
			key, _ := nextToken(args)
			if v, ok := cache.Get(key); ok {
				out.WriteString(v)
			} else {
				out.WriteString("NULL")
			}
			out.WriteByte('\n')
		case "DEL":
			key, _ := nextToken(args)
			if cache.Delete(key) {
				out.WriteString("1\n")
			} else {
				out.WriteString("0\n")
			}
		case "SIZE":
			num = strconv.AppendInt(num[:0], int64(cache.Len()), 10)
			num = append(num, '\n')
			out.Write(num)
		}
	}
	return out.Flush()
}

// parseCapacity reads the leading decimal digits of s. A missing or
// out-of-range number yields 0.
func parseCapacity(s []byte) int {
	end := 0
	for end < len(s) && s[end] >= '0' && s[end] <= '9' {
		end++
	}
	n, err := strconv.ParseInt(string(s[:end]), 10, 0)
	if err != nil {
		return 0
	}
	return int(n)
}

// trim strips leading spaces/tabs and trailing spaces, tabs and carriage returns.
func trim(s []byte) []byte {
	s = bytes.TrimRight(s, " \t\r")
	return bytes.TrimLeft(s, " \t")
}

// nextToken splits off the next space-separated token from s.
func nextToken(s []byte) (tok, rest []byte) {
	tok, rest, _ = bytes.Cut(s, []byte{' '})
	return tok, rest
}
